.docs-layout {
  display: grid;
  grid-template-columns: 17rem minmax(0, 1fr);
  align-items: start;
  gap: clamp(2rem, 4vw, 4rem);
  max-width: 86rem;
  margin-inline: auto;
  padding: 2.5rem clamp(1.25rem, 4vw, 4rem);
}

.docs-sidebar {
  position: sticky;
  top: 1rem;
}

.docs-navigation-panel summary {
  padding-block: 0.5rem;
  font-weight: 600;
  cursor: pointer;
}

.app-shell .docs-navigation {
  display: block;
  max-height: 70vh;
  overflow-y: auto;
  border: 0;
  padding: 0.75rem 0.75rem 0 0;
  font-size: 0.9375rem;
  line-height: 1.5;
}

.docs-navigation section + section {
  margin-top: 1.5rem;
}

.docs-navigation section > a {
  display: inline-block;
  font-weight: 600;
}

.app-shell .docs-navigation ul {
  display: grid;
  gap: 0.25rem;
  padding: 0.5rem 0 0;
}

.docs-navigation li a {
  display: block;
  padding: 0.25rem 0.5rem;
  color: #526071;
  text-decoration: none;
}

.docs-navigation a[aria-current="page"] {
  color: #172033;
  font-weight: 600;
  text-decoration: underline;
  text-underline-offset: 0.25em;
}

.docs-navigation a:hover {
  color: #172033;
  text-decoration: underline;
  text-underline-offset: 0.25em;
}

.docs-article {
  min-width: 0;
  max-width: 72ch;
  font-size: 1.0625rem;
  line-height: 1.75;
}

.docs-article h1 {
  margin: 0 0 1.5rem;
  font-size: clamp(2rem, 4vw, 3rem);
  line-height: 1.15;
  text-wrap: balance;
}

.docs-article h2,
.docs-article h3 {
  margin-top: 2.5rem;
  margin-bottom: 0.75rem;
  line-height: 1.3;
  text-wrap: balance;
}

.docs-article a {
  color: #075985;
  text-underline-offset: 0.2em;
}

.docs-article figure {
  margin: 1.5rem 0;
}

.docs-article figcaption {
  border-bottom: 1px solid #d6dde7;
  padding: 0.5rem 0.75rem;
  font-size: 0.875rem;
}

.docs-article pre {
  max-width: 100%;
  overflow-x: auto;
  border: 1px solid #d6dde7;
  border-radius: 0.375rem;
  padding: 1rem;
  font-size: 0.875rem;
  line-height: 1.6;
}

.docs-table-scroll {
  max-width: 100%;
  overflow-x: auto;
}

.docs-article table {
  border-collapse: collapse;
  font-size: 0.9375rem;
}

.docs-article th,
.docs-article td {
  border: 1px solid #d6dde7;
  padding: 0.625rem 0.75rem;
  text-align: left;
}

.docs-article img,
.docs-article svg {
  max-width: 100%;
  height: auto;
}

.docs-state {
  max-width: 72ch;
  margin: 3rem auto;
  padding: 1.5rem;
  line-height: 1.7;
}

.docs-navigation-panel summary:focus-visible,
.docs-table-scroll:focus-visible {
  outline: 3px solid #2563eb;
  outline-offset: 0.25rem;
}

@media (max-width: 52rem) {
  .docs-layout {
    display: block;
    padding-top: 1.5rem;
  }

  .docs-sidebar {
    position: static;
    margin-bottom: 2rem;
  }

  .app-shell .docs-navigation {
    max-height: 16rem;
  }
}

